style:
.tw-cosolar--zhusha.resume-paper {
  color: #2b2424;
}

.tw-cosolar--zhusha.resume-paper .paper-header {
  position: relative;
  align-items: flex-start;
  gap: 8mm;
  margin: 0 0 5mm;
  padding: 0 0 4mm;
  border: none;
  border-bottom: 1.5px solid #c0262d;
  text-align: left;
}

.tw-cosolar--zhusha.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2.4mm;
  background: #c0262d;
  print-color-adjust: exact;
}

.tw-cosolar--zhusha.resume-paper .paper-name {
  color: #231d1d;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.15);
  letter-spacing: 0.1em;
}

.tw-cosolar--zhusha.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #7c6d6d;
}

.tw-cosolar--zhusha.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #c0262d;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.tw-cosolar--zhusha.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7c2a2e;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.94);
}

.tw-cosolar--zhusha.resume-paper .paper-contacts--labeled {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 6mm;
  margin-top: 2.8mm;
  color: #3c3232;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--zhusha.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--zhusha.resume-paper .paper-contact__label {
  color: #8c7a7a;
}

.tw-cosolar--zhusha.resume-paper .paper-photo {
  width: 26mm;
  height: 34mm;
  padding: 1.6mm;
  print-color-adjust: exact;
}

.tw-cosolar--zhusha.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background-color: #fbf1f1;
  background-clip: border-box;
  color: #c0262d;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-section__title {
  display: block;
  margin-bottom: 2.6mm;
  padding: 0 0 1.2mm;
  border-bottom: 1.5px dotted #c0262d;
  color: #221d1d;
  font-size: calc(var(--paper-base-size) * 1.12);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-section__icon {
  display: none;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-section__body {
  color: #332b2b;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-item-title {
  color: #1c1c1c;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-item-period {
  color: #6f5a5a;
  font-weight: 600;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-item-sub {
  color: #4a3f3f;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-note__tag {
  color: #c0262d;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-item-tag {
  background: #fdf2f2;
  color: #c0262d;
  border: 0.2mm solid #ecc9ca;
  print-color-adjust: exact;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-rich ul {
  margin: 0.6mm 0 0;
  padding-left: 0;
  list-style: none;
  counter-reset: zhusha-li;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-rich ul > li {
  position: relative;
  margin: 0.4mm 0;
  padding-left: 5mm;
  counter-increment: zhusha-li;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-rich ul > li::before {
  content: counter(zhusha-li) "、";
  position: absolute;
  left: 0;
  color: #a32429;
  font-weight: 600;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-skill {
  border-bottom-color: #f0e4e4;
}

.tw-cosolar--zhusha.resume-paper .paper-section .paper-skill__level {
  color: #c0262d;
}

.tw-cosolar--zhusha.resume-paper .paper-footer {
  border-top: 1px solid #eadede;
  color: #7d6f6f;
}
